        TestSuite suite = new TestSuite(
                "Test all .test files in 'ProjectFortress/library_tests' ");
        //$JUnit-BEGIN$
        suite.addTest(FileTests.compilerSuite(testDir1, true, failsOnly, false));
        return suite;
    }

